  perform 1 from catalog._compute_suggested_prices(100, p_list_markup_ratio, p_floor_markup_ratio);

  insert into catalog.store_price_rules (
    tenant_id,
    name,
    calculation_type,
    list_markup_ratio,
    floor_markup_ratio,
    status,
    updated_at
